<?php
defined('ABSPATH') || exit;
final class TNet_Community_Topic_Composer_Controller {
    private const COMMUNITIES=['community:local-demo'=>'Local Community Demo']; private const MODES=['discussion'=>'Discussion','question'=>'Question','candle'=>'Candle (coming soon)','idea'=>'Idea (coming soon)']; private static array $created=[];
    public static function register():void{if(!self::local())return;add_rewrite_rule('^community/new/?$','index.php?tnet_community_topic_composer=1','top');add_filter('query_vars',static function(array $v):array{$v[]='tnet_community_topic_composer';return $v;});add_action('template_redirect',[self::class,'render']);}
    private static function local():bool{return defined('DDEV_PROJECT')||(bool)getenv('DDEV_PROJECT');}
    public static function render():void{if(!get_query_var('tnet_community_topic_composer'))return;if(!is_user_logged_in()||!current_user_can('read'))auth_redirect();if('POST'===strtoupper($_SERVER['REQUEST_METHOD']??''))self::submit();self::form([]);exit;}
    private static function urls(string $body):array{preg_match_all('~https://[^\s<>"\']+~i',$body,$m);$out=[];foreach($m[0]??[] as $u){$u=rtrim($u,".,!?;:)");if(!in_array($u,$out,true))$out[]=$u;}return $out;}
    private static function upload(string $alt):?array{if(empty($_FILES['image_file']['tmp_name']))return null;$f=$_FILES['image_file'];if((int)$f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Image upload failed.');if((int)$f['size']>10485760)throw new RuntimeException('Choose an image up to 10 MB.');$check=wp_check_filetype_and_ext($f['tmp_name'],$f['name']);if(!in_array($check['type']??'', ['image/jpeg','image/png','image/webp'],true))throw new RuntimeException('Choose a JPEG, PNG, or WebP image.');if(trim($alt)==='')throw new RuntimeException('Add alt text before uploading the image.');require_once ABSPATH.'wp-admin/includes/file.php';$r=wp_handle_upload($f,['test_form'=>false,'mimes'=>['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp']]);if(isset($r['error']))throw new RuntimeException('Image upload failed.');$relative=str_replace(wp_upload_dir()['basedir'].'/','',$r['file']);$ref='wp-content/uploads/'.$relative;$a=['attachment_id'=>'upload:'.substr(hash('sha256',$relative),0,16),'attachment_type'=>'image','source_kind'=>'local_upload','source_reference'=>$ref,'title'=>sanitize_file_name($f['name']),'description'=>'Locally staged Community image.','alt_text'=>$alt,'mime_type'=>$r['type'],'file_size'=>(int)$f['size'],'rights_status'=>'author_declared','moderation_state'=>'clear','lifecycle_state'=>'active','created_at'=>gmdate('Y-m-d H:i:s')];self::$created[]=$r['file'];return $a;}
    private static function cleanup():void{foreach(self::$created as $p)if(is_string($p)&&is_file($p))@unlink($p);self::$created=[];}
    private static function submit():void{if(!isset($_POST['tnet_topic_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tnet_topic_nonce'])),'tnet_community_topic'))self::form(['Nonce verification failed.']);$community=sanitize_text_field(wp_unslash($_POST['community_id']??''));$sid=sanitize_text_field(wp_unslash($_POST['submission_id']??''))?:'web-'.wp_generate_uuid4();$title=sanitize_text_field(wp_unslash($_POST['title']??''));$body=sanitize_textarea_field(wp_unslash($_POST['body']??''));$mode=sanitize_key(wp_unslash($_POST['post_mode']??'discussion'));$urls=self::urls($body);$selected=esc_url_raw(wp_unslash($_POST['representative_url']??''));$representative=in_array($selected,$urls,true)?$selected:($urls[0]??'');$choice=sanitize_key(wp_unslash($_POST['preview_choice']??'keep'));$alt=sanitize_text_field(wp_unslash($_POST['attachment_alt']??''));$errors=[];if(!isset(self::COMMUNITIES[$community]))$errors[]='Choose a valid Community.';if($title==='')$errors[]='Enter a topic title.';if($body==='')$errors[]='Enter the topic body.';if(!isset(self::MODES[$mode]))$mode='discussion';$attachment=null;try{$attachment=self::upload($alt);}catch(Throwable $e){$errors[]=$e->getMessage();}if($errors){self::cleanup();self::form($errors,compact('community','sid','title','body','mode','representative','choice','alt'));}try{$preview=(new TNet_Community_Link_Attachment_Service())->prepare($representative,$choice);$draft=['submission_id'=>$sid,'community_id'=>$community,'author_id'=>'user:'.(int)get_current_user_id(),'post_type'=>'topic','title'=>$title,'body'=>$body,'parent_post_id'=>null,'visibility'=>'public','publication_mode'=>'post_first','moderation_input'=>'clear','compatibility_refs'=>['composer'=>['post_mode'=>$mode,'attachments'=>$attachment?[$attachment]:[],'links'=>array_map(static fn($u)=>['url'=>$u,'enrichment'=>'mocked'],$urls),'preview'=>$preview,'representative_url'=>$representative]],'audit_context'=>['source'=>'local-natural-composer']];$result=(new TNet_Community_Publisher_Application())->publish_and_persist($draft,self::COMMUNITIES,['actor_id'=>$draft['author_id']]);if(empty($result['accepted']))throw new RuntimeException('The topic could not be published. Please try again.');}catch(Throwable $e){self::cleanup();self::form([$e->getMessage()],compact('community','sid','title','body','mode','representative','choice','alt'));}$path=str_replace('%3A',':',rawurlencode($result['post']['post_id']));wp_safe_redirect(home_url('/community/thread/'.$path.'/'));exit;}
    private static function form(array $errors,array $v=[]):void{$community=$v['community']??'community:local-demo';$sid=$v['sid']??'web-'.wp_generate_uuid4();$title=$v['title']??'';$body=$v['body']??'';$mode=$v['mode']??'discussion';$representative=$v['representative']??'';$choice=$v['choice']??'keep';$alt=$v['alt']??'';status_header(200);nocache_headers();header('X-Robots-Tag: noindex,nofollow');$html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Start a Discussion | Teachers.Net</title><style>body{font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.5;color:#1d2327}main{border:1px solid #ccd0d4;border-radius:8px;padding:clamp(1rem,4vw,2rem)}label{display:block;font-weight:600;margin:.9rem 0 .35rem}input,select,textarea{box-sizing:border-box;width:100%;border:1px solid #8c8f94;border-radius:4px;padding:.65rem;font:inherit}textarea{min-height:12rem}.section{border-top:1px solid #dcdcde;margin-top:1.25rem;padding-top:1rem}.hint,.status{color:#646970;font-size:.92rem}.staged{border:1px dashed #8c8f94;border-radius:6px;padding:1rem;margin-top:.75rem}.actions{display:flex;gap:1rem;margin-top:1.25rem}button{background:#135e96;color:#fff;border:0;border-radius:4px;padding:.7rem 1rem;font:inherit;font-weight:600}.secondary{background:#fff;color:#135e96;border:1px solid #135e96}.dropzone{border:2px dashed #8c8f94;border-radius:6px;padding:1rem;text-align:center}.dropzone.active{border-color:#135e96;background:#eef6fc}.preview{border:1px solid #dcdcde;border-radius:6px;padding:.75rem;margin-top:.75rem}.preview a{font-weight:600}</style></head><body><main><p><a href="'.esc_url(home_url('/community/')).'">← Community</a></p><h1>Start a Discussion</h1>';if($errors)$html.='<div role="alert"><ul>'.implode('',array_map(static fn($e)=>'<li>'.esc_html($e).'</li>',$errors)).'</ul><p>Please reselect the image if the browser cleared the file input.</p></div>';$html.='<form method="post" enctype="multipart/form-data">'.wp_nonce_field('tnet_community_topic','tnet_topic_nonce',true,false).'<input type="hidden" name="submission_id" value="'.esc_attr($sid).'"/><section class="section"><label for="community_id">Community</label><select id="community_id" name="community_id"><option value="community:local-demo">Local Community Demo</option></select><label for="post_mode">Post type</label><select id="post_mode" name="post_mode">';foreach(self::MODES as $k=>$label)$html.='<option value="'.esc_attr($k).'"'.selected($mode,$k,false).'>'.esc_html($label).'</option>';$html.='</select></section><section class="section"><label for="title">Title</label><input id="title" name="title" value="'.esc_attr($title).'" required><label for="body">Body</label><textarea id="body" name="body" required>'.$body.'</textarea><p class="hint">Paste or type a link; the first eligible link gets a mocked preview.</p><div id="staged-content" class="staged" aria-live="polite"><p id="image-status" class="status">Empty: paste, drop, or select one image.</p><div id="dropzone" class="dropzone">Drop one JPEG, PNG, or WebP image here<br><label for="image_file">Choose a photo</label><input id="image_file" name="image_file" type="file" accept="image/jpeg,image/png,image/webp"></div><div id="image-preview"></div><button type="button" class="secondary" id="remove-image">Remove image</button><label for="attachment_alt">Image alt text</label><input id="attachment_alt" name="attachment_alt" value="'.esc_attr($alt).'" type="text"><p class="hint">Required when an image is staged.</p></div><label for="representative_url">Representative link</label><select id="representative_url" name="representative_url"><option value="">No link preview</option></select><label for="preview_choice">Preview</label><select id="preview_choice" name="preview_choice"><option value="keep"'.selected($choice,'keep',false).'>Keep preview</option><option value="remove"'.selected($choice,'remove',false).'>Dismiss preview</option><option value="raw"'.selected($choice,'raw',false).'>Keep link only</option></select><div id="link-preview" class="preview" hidden></div></section><div class="actions"><button type="submit">Publish Topic</button><a href="'.esc_url(home_url('/community/')).'">Cancel</a></div></form></main><script>';
        $html.='(function(){const b=document.getElementById("body"),s=document.getElementById("representative_url"),f=document.getElementById("image_file"),d=document.getElementById("dropzone"),st=document.getElementById("image-status"),pr=document.getElementById("image-preview"),rm=document.getElementById("remove-image"),alt=document.getElementById("attachment_alt"),lp=document.getElementById("link-preview"),pc=document.getElementById("preview_choice");let objectUrl=null;const urls=()=>[...new Set((b.value.match(/https:\/\/[^\\s<>"\']+/gi)||[]).map(u=>u.replace(/[.,!?;:)]+$/,"")))];function links(){const old=s.value;const us=urls();s.innerHTML="<option value=\"\">No link preview</option>";us.forEach(u=>{const o=document.createElement("option");o.value=u;o.textContent=u;s.appendChild(o)});s.value=us.includes(old)?old:(us[0]||"");preview()}function preview(){const u=s.value;lp.hidden=!u||pc.value!=="keep";lp.textContent=lp.hidden?"":"Mocked preview: "+u}function clear(){if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=null;f.value="";pr.innerHTML="";alt.required=false;st.textContent="Empty: paste, drop, or select one image."}function stage(file){if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>10485760){clear();st.textContent="Error: choose a JPEG, PNG, or WebP image up to 10 MB.";return}if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);try{const dt=new DataTransfer();dt.items.add(file);f.files=dt.files}catch(e){st.textContent="Error: reselect the image with Choose a photo.";return}st.textContent="Staged: "+file.name+" (ready to submit)";pr.innerHTML="<img src=\""+objectUrl+"\" alt=\"\" style=\"max-width:100%;max-height:240px\"><p>"+file.name+"</p>";alt.required=true}b.addEventListener("input",links);s.addEventListener("change",preview);pc.addEventListener("change",preview);f.addEventListener("change",e=>stage(e.target.files[0]));rm.addEventListener("click",clear);["dragenter","dragover"].forEach(x=>d.addEventListener(x,e=>{e.preventDefault();d.classList.add("active")}));["dragleave","drop"].forEach(x=>d.addEventListener(x,e=>{e.preventDefault();d.classList.remove("active")}));d.addEventListener("drop",e=>stage(e.dataTransfer.files[0]));b.addEventListener("paste",e=>{for(const item of (e.clipboardData?.items||[])){if(item.kind==="file"&&item.type.startsWith("image/")){e.preventDefault();stage(item.getAsFile());break}}});window.addEventListener("unload",()=>{if(objectUrl)URL.revokeObjectURL(objectUrl)});links();})();</script></body></html>';
        echo $html;
    }
}
